const fs = require('fs');
const code = fs.readFileSync('app/_layout.tsx', 'utf8');
const providers = ['QueryClientProvider', 'I18nProvider', 'AuthProvider', 'AnalyticsProvider', 'IPXProvider', 'WalletProvider', 'EarnProvider', 'EmailProvider', 'NetworkProvider', 'ProviderMountProbe'];
let allBalanced = true;
providers.forEach(p => {
  const open = (code.match(new RegExp('<'+p+'[ >]', 'g')) || []).length;
  const close = (code.match(new RegExp('</'+p+'>', 'g')) || []).length;
  const balanced = open === close;
  if (!balanced) allBalanced = false;
  console.log(p + ': open=' + open + ' close=' + close + (balanced ? ' OK' : ' MISMATCH'));
});
const pbOpen = (code.match(/<ProviderBoundary[ >]/g) || []).length;
const pbClose = (code.match(/<\/ProviderBoundary>/g) || []).length;
console.log('ProviderBoundary: open=' + pbOpen + ' close=' + pbClose + (pbOpen === pbClose ? ' OK' : ' MISMATCH'));
if (!allBalanced || pbOpen !== pbClose) { process.exit(1); }
console.log('\nAll JSX tags balanced!');
"

