try {
  const ts = require('typescript');
  const fs = require('fs');
  const code = fs.readFileSync('app/_layout.tsx', 'utf8');
  const result = ts.transpileModule(code, {
    compilerOptions: { jsx: ts.JsxEmit.React, target: ts.ScriptTarget.ES2020, module: ts.ModuleKind.CommonJS },
    reportDiagnostics: true,
  });
  const diags = result.diagnostics || [];
  const errors = diags.filter(d => d.category === ts.DiagnosticCategory.Error);
  if (errors.length === 0) {
    console.log('TypeScript transpile: OK — no syntax errors');
  } else {
    errors.forEach(e => console.log('ERROR:', ts.flattenDiagnosticMessageText(e.messageText, '\n')));
    process.exit(1);
  }
} catch(e) {
  // typescript not installed, try basic JSX parse
  console.log('TypeScript module not available, checking basic syntax...');
  const fs = require('fs');
  const code = fs.readFileSync('app/_layout.tsx', 'utf8');
  // Check for common issues
  const openBraces = (code.match(/{/g) || []).length;
  const closeBraces = (code.match(/}/g) || []).length;
  console.log('Braces: open=' + openBraces + ' close=' + closeBraces + (openBraces === closeBraces ? ' OK' : ' MISMATCH'));
  const openParens = (code.match(/\(/g) || []).length;
  const closeParens = (code.match(/\)/g) || []).length;
  console.log('Parens: open=' + openParens + ' close=' + closeParens + (openParens === closeParens ? ' OK' : ' MISMATCH'));
  if (openBraces !== closeBraces || openParens !== closeParens) process.exit(1);
  console.log('Basic syntax check passed');
}
"

